const stockClaims={},backflush=[];for(const item of consumptions){if(item.status!=='pending_backflush')throw new Error((item.item_code||item.name)+' 材料耗用状态已变化');const plan=await ctx.api.object('forge_subcontract_material_plan').findOne({where:{id:item.plan_id}});if(!plan||plan.order_id!==order.id)throw new Error('材料耗用计划与订单不一致');const stocks=await ctx.api.object('forge_subcontract_stock_balance').find({where:{balance_key:inbound.supplier_id+':'+order.id+':'+item.sku_id}});if(stocks.length!==1)throw new Error((item.item_code||item.name)+' 委外厂库存余额不存在或重复');const stock=stocks[0],actual=Number(item.actual_quantity||0);stockClaims[stock.id]=round((stockClaims[stock.id]||0)+actual);if(stockClaims[stock.id]>Number(stock.on_hand_quantity||0))throw new Error((item.item_code||item.name)+' 委外厂在外库存不足');backflush.push({item,plan,stock,actual});}
